{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C01","C02","C03","C04","C05","C06","C07","C08","C09","C10","C11","C12","C13","C14","C15","C16","C17","C18","C19","C20","C21","C23","C24","C25","C27","C28"],
  "contradictory_card_ids": ["C22","C26","C29"],
  "prediction_basis_card_ids": ["C01","C11","C13","C16","C18","C04","C05","C14"],
  "claims": [
    {
      "claim": "Pramipexole, a small basic amine that is ionized at physiological pH, shows quasi-complete absorption with oral bioavailability above 90 percent, demonstrating that full ionization does not preclude F at or above 20 percent.",
      "card_ids": ["C01"]
    },
    {
      "claim": "5-Hydroxytryptophan, an ionized indole amino acid, has a mean absolute oral bioavailability of 49 percent in humans and 40 percent in mice, supporting adequate F for ionized indole-like structures.",
      "card_ids": ["C11","C18"]
    },
    {
      "claim": "Labetalol, a basic amine with a phenol and primary carboxamide, has 63 percent oral bioavailability in cirrhotic patients and 33 percent in age-matched controls, both above the 20 percent threshold, supporting F for basic carboxamide-containing molecules even without cirrhosis.",
      "card_ids": ["C13","C16","C17","C24"]
    },
    {
      "claim": "AZD0837, a prodrug with a basic amidine group, has absolute oral bioavailability of 22 to 55 percent, providing the lowest reference range and still remaining at or above the 20 percent threshold.",
      "card_ids": ["C04","C05","C14","C20"]
    },
    {
      "claim": "Other reference contexts report F values of 38 to 103 percent (PF-05241328, cilomilast, leucovorin, 1,25(OH)2D2, ebastine), none below 20 percent.",
      "card_ids": ["C02","C03","C07","C08","C10","C12","C25","C27"]
    },
    {
      "claim": "The qualitative 'low/poor' bioavailability statements for ebastine are relative descriptors and do not overturn the measured ~40 percent F; isradipine's non-cirrhotic baseline F of 16 percent is condition-specific and structurally dissimilar to the query.",
      "card_ids": ["C22","C26","C29"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C15","C16","C17","C18","C19","C20","C21","C23","C24","C25","C27","C28"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C22","C26","C29"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability for the query molecule; prediction relies on transfer from reference contexts.",
    "First-pass metabolism and transporter-mediated absorption for the query are not directly assessed.",
    "The isradipine context is conditioned on cirrhosis; its non-cirrhotic baseline F (16%) is below threshold but structurally dissimilar, limiting transfer.",
    "Qualitative 'low/poor' bioavailability statements for ebastine lack threshold-relevant absolute values and are outweighed by the measured ~40% F.",
    "Physicochemical prior indicates poor passive permeability, but reference contexts show ionized basic amines can still achieve F≥20%."
  ],
  "decision_summary": "L2 records largely reinforce the L1 picture: labetalol is 33% bioavailable even in controls, 5-HTP is 40% in mice, and repeated absolute F values for AZD0837, PF-05241328, cilomilast, and 1,25(OH)2D2 remain at or above 20%. The qualitative 'low' ebastine statements and isradipine's non-cirrhotic baseline 16% are either relative descriptors or condition/structure-specific and do not overturn the high prediction. F≥20% remains better supported."
}

